package classworks;

public class CntrlStmnt3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num1 = 25;
        int num2 = 39;

        if (num1 != num2) {
            System.out.println(num1 + " != " + num2);
        }

        if (num1 < num2) {
            System.out.println(num1 + " < " + num2);
        }

        if (num1 <= num2) {
            System.out.println(num1 + " <= " + num2);
        }

	}

}
